LESSONS = []
for _skey, _spec in SUBJECTS.items():
    if _spec[3] != 2:
        continue
    for _first, _last, _unit, _codes in _spec[4]:
        _queue = list(MORE.get((_skey, _unit), []))
        if not _queue:
            continue
        _extra = 0
        for _week in range(_first, _last + 1):
            for _slot in range(2):
                if _queue:
                    _text = _queue.pop(0)
                else:
                    _extra += 1
                    _text = "%s: extra planned lesson %d" % (_unit, _extra)
                LESSONS.append(_make(_skey, _week, _slot, _unit, _codes, _text))

if __name__ == "__main__":
    keys = [x["seed_key"] for x in LESSONS]
    assert len(keys) == len(set(keys)), "duplicate seed keys"
    for (_k, _u), _topics in MORE.items():
        _unit = [u for u in SUBJECTS[_k][4] if u[2] == _u][0]
        _slots = (_unit[1] - _unit[0] + 1) * 2
        if len(_topics) != _slots:
            print("COUNT MISMATCH", _k, _u, len(_topics), "topics for", _slots, "slots")
    for _k in {k for k, _u in MORE}:
        _texts = [t for (k, _u), ts in MORE.items() if k == _k for t in ts]
        assert len(_texts) == len(set(_texts)), (_k, "repeated lesson topics")
    print("lessons:", len(LESSONS))
